cd /opt/nxeon && node -e '
import("./scripts/blog-seed-lib.mjs").then(async ({db, slugify})=>{
  const titles=["How to Install Forge on a Minecraft Server","How to Install Fabric on a Minecraft Server","How to Whitelist Players on a Minecraft Server","How to Set Up a Minecraft Bedrock Dedicated Server"];
  const posts=await db.blogPost.findMany({where:{slug:{in:titles.map(slugify)}},select:{slug:true,body:true}});
  const strip=(md)=>{
    let t=md.replace(/```[\s\S]*?```/g,"");         // remove fenced code
    t=t.replace(/`[^`]*`/g,"");                       // inline code
    t=t.replace(/\[([^\]]+)\]\([^)]+\)/g,"$1");       // links -> anchor text
    t=t.replace(/[#>*_{}-]/g," ");                    // md punctuation
    return t.split(/\s+/).filter(Boolean).length;
  };
  for(const p of posts){
    const raw=p.body.split(/\s+/).filter(Boolean).length;
    const prose=strip(p.body);
    console.log(`raw=${raw} prose-only(no code)=${prose}  ${p.slug}`);
  }
  await db.$disconnect();
});
'
